function Tag(prefix, name) {
  this.full = prefix + ":" + name;
}
const holder = { full: "old", Tag };
const BoundTag = Tag.bind(holder, "v1");
const t1 = new BoundTag("ok");
const t2 = new holder.Tag("v2", "go");
console.log(t1.full);
console.log(t2.full);
console.log(holder.full);
console.log(t1 instanceof Tag);
